contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint256 newDifficulty, uint256 initialDifficulty) public {
        require(address(c).balance >= 0);
        // Set up a known initial difficulty (owner here is this contract).
        c.AdjustDifficulty(initialDifficulty); if (__ESBMC_reverted()) return;
        uint256 before = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        // Non-owner attempt: not possible directly since msg.sender is the owner.
        // Instead, verify owner can set any value.
        c.AdjustDifficulty(newDifficulty); if (__ESBMC_reverted()) return;
        uint256 afterOwner = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        assert(afterOwner == newDifficulty && before == initialDifficulty);
    }
}

