// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newDifficulty, uint256 initialDifficulty) internal {
        vm.assume(address(c).balance >= 0);
        try c.AdjustDifficulty(initialDifficulty) {} catch { return; }
        uint256 before;
        try c.currentDifficulty() returns (uint256 __r) { before = __r; } catch { return; }
        try c.AdjustDifficulty(newDifficulty) {} catch { return; }
        uint256 afterOwner;
        try c.currentDifficulty() returns (uint256 __r) { afterOwner = __r; } catch { return; }
        assertTrue(afterOwner == newDifficulty && before == initialDifficulty);
    }

    function testFuzz_run(uint256 newDifficulty, uint256 initialDifficulty) public {
        _run(newDifficulty, initialDifficulty);
    }

    receive() external payable {}
}
